type ProductLink={id:number;url:string;loja:string}
type QuoteLinkDraft={id:string;url:string}
type PurchaseItem={id:number;descricao:string;quantidade:string|null;unidade:string|null;observacao:string|null;valor_unitario:string|null;valor_desconto:string|null;valor_total:string|null;valor_total_manual:boolean;ordem:number;links_cotacao:ProductLink[];quantidade_documentos:number;documentos_legados_habilitados:boolean;etapa?:string|null;fornecedor?:string|null;contato_fornecedor?:string|null;nome_contato_fornecedor?:string|null;chave_pix?:string|null;status?:PaymentStatus;forma_pagamento?:string|null;data_pagamento?:string|null;data_agendamento?:string|null;data_entrega?:string|null}
type Purchase={id:number;descricao:string;etapa_id:number|null;etapa:string|null;etapa_cor:string|null;etapa_ordem:number|null;documento:'Orçamento'|'Nota Fiscal';status:PaymentStatus;data_pagamento:string|null;forma_pagamento:string|null;fornecedor:string|null;nome_contato_fornecedor:string|null;contato_fornecedor:string|null;observacao:string|null;valor_desconto:string|null;numero_nota_fiscal:string|null;data_emissao:string|null;data_agendamento:string|null;data_entrega:string|null;ordem:number;valor_total:string;itens:PurchaseItem[];quantidade_documentos:number}
type PurchaseList={compras?:Purchase[];despesas?:Purchase[];itens_orfaos:PurchaseItem[];total:number}
type Supplier={fornecedor:string;nome_contato_fornecedor:string|null;contato_fornecedor:string|null}
type PaymentDocument={id:number;titulo:string;categoria:string;url:string|null;nome_original:string|null;tipo_origem:'LINK'|'ARQUIVO';criado_em:string}
type PaymentDocumentDraft={id:string;titulo:string;source:'LINK'|'ARQUIVO';url:string|null;file:File|null}

const dateInput=(value:string|null|undefined)=>value?.slice(0,10)||''
const validQuoteUrl=(value:string)=>{try{const url=new URL(value.trim());return url.protocol==='http:'||url.protocol==='https:'}catch{return false}}
const paymentDocumentForm=(draft:PaymentDocumentDraft)=>{const form=new FormData();form.set('titulo',draft.titulo);form.set('categoria','Despesas');if(draft.source==='LINK'&&draft.url)form.set('url',draft.url);if(draft.source==='ARQUIVO'&&draft.file)form.set('arquivo',draft.file);return form}
const currencyDigits=(value:string|number|null|undefined)=>String(value??'').replace(/\D/g,'')
const formatCurrencyInput=(value:string|number|null|undefined)=>{const digits=currencyDigits(value);if(!digits)return '';return (Number(digits)/10_000).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})}
const formatStoredUnitValue=(value:string|number|null|undefined)=>value===null||value===undefined||value===''?'':Number(value).toLocaleString('pt-BR',{minimumFractionDigits:4,maximumFractionDigits:4})
const currencyInputValue=(value:string)=>{const digits=currencyDigits(value);return digits?(Number(digits)/10_000).toFixed(4):''}
const currencyNumber=(value:string)=>{const normalized=currencyInputValue(value);return normalized?Number(normalized):null}
const formatMoneyInput=(value:string|number|null|undefined)=>{const digits=currencyDigits(value);if(!digits)return '';return (Number(digits)/100).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})}
const formatStoredMoney=(value:string|number|null|undefined)=>value===null||value===undefined||value===''?'':Number(value).toLocaleString('pt-BR',{minimumFractionDigits:2,maximumFractionDigits:2})
const moneyInputValue=(value:string)=>{const digits=currencyDigits(value);return digits?(Number(digits)/100).toFixed(2):''}
const moneyInputNumber=(value:string)=>{const normalized=moneyInputValue(value);return normalized?Number(normalized):null}
const localPhoneDigits=(value:string|number|null|undefined)=>{let digits=String(value??'').replace(/\D/g,'');if(digits.startsWith('00'))digits=digits.slice(2);if(digits.startsWith('55')&&digits.length>=12)digits=digits.slice(2);if(digits.startsWith('0'))digits=digits.slice(1);return digits.slice(0,11)}
const formatSupplierPhone=(value:string|number|null|undefined)=>{const digits=localPhoneDigits(value);if(!digits)return '+55 ';const ddd=digits.slice(0,2);const number=digits.slice(2);if(digits.length<=2)return `+55 (${ddd}`;if(number.length<=4)return `+55 (${ddd}) ${number}`;return `+55 (${ddd}) ${number.slice(0,number.length===9?5:4)}-${number.slice(number.length===9?5:4)}`}

function PaymentLinks({projectId,item,drafts=[],onDraftsChange,editable=false}:{projectId:string;item?:PurchaseItem;drafts?:QuoteLinkDraft[];onDraftsChange?:(links:QuoteLinkDraft[])=>void;editable?:boolean}){
  const client=useQueryClient();const[url,setUrl]=useState('');const[error,setError]=useState('');const[links,setLinks]=useState<ProductLink[]>(item?.links_cotacao||[])
  const endpoint=`/projetos/${projectId}/despesas/${item?.id||0}/links`
  const add=useMutation({mutationFn:(value:string)=>api<{link:ProductLink}>(endpoint,{method:'POST',...jsonBody({url:value})}),onSuccess:result=>{setLinks(current=>current.some(link=>link.id===result.link.id)?current:[...current,result.link]);setUrl('');void client.invalidateQueries({queryKey:['despesas',projectId]})}})
  const remove=useMutation({mutationFn:(id:number)=>api(`${endpoint}/${id}`,{method:'DELETE'}),onSuccess:(_,id)=>{setLinks(current=>current.filter(link=>link.id!==id));void client.invalidateQueries({queryKey:['despesas',projectId]})}})
  const visible=item?links:drafts
  const addLink=()=>{const normalized=url.trim();if(!validQuoteUrl(normalized)){setError('Informe uma URL válida iniciada por http:// ou https://.');return}if(visible.some(link=>link.url===normalized)){setError('Este link já foi adicionado.');return}if(item)add.mutate(normalized);else{onDraftsChange?.([...drafts,{id:crypto.randomUUID(),url:normalized}]);setUrl('')}setError('')}
  return <section className="payment-resource-panel"><header><div><Link2/><strong>Links de cotação</strong><span>{visible.length}</span></div></header><div className="quote-link-list">{visible.map(link=><div key={link.id}><Link2/><strong>{item?(link as ProductLink).loja:'Link de cotação'}</strong><a className="quote-url" href={link.url} target="_blank" rel="noopener noreferrer">{link.url}</a><button type="button" title="Copiar link" onClick={()=>void navigator.clipboard.writeText(link.url)}><Copy/></button><a href={link.url} target="_blank" rel="noopener noreferrer"><ExternalLink/></a>{editable&&<button className="danger" type="button" title="Remover link" onClick={()=>item?remove.mutate(Number(link.id)):onDraftsChange?.(drafts.filter(current=>current.id!==link.id))}><Trash2/></button>}</div>)}</div>{editable&&<div className="resource-inline-form"><input value={url} onChange={event=>{setUrl(event.target.value);setError('')}} type="url" placeholder="https://fornecedor.com/cotacao"/><button type="button" className="app-button" disabled={!validQuoteUrl(url)||add.isPending} onClick={addLink}><Plus/>Adicionar</button></div>}{error&&<small className="payment-document-form-error">{error}</small>}</section>
}

function LegacyPurchaseDocuments({projectId,purchaseId,editable=false,drafts=[],onDraftsChange}:{projectId:string;purchaseId?:number;itemId?:number;purchases:Purchase[];editable?:boolean;drafts?:PaymentDocumentDraft[];onDraftsChange?:(documents:PaymentDocumentDraft[])=>void}){
  const client=useQueryClient();const[source,setSource]=useState<'LINK'|'ARQUIVO'>('LINK');const[title,setTitle]=useState('');const[url,setUrl]=useState('');const[file,setFile]=useState<File|null>(null);const[error,setError]=useState('')
  const endpoint=`/projetos/${projectId}/despesas/despesas/${purchaseId||0}/documentos`
  const documents=useQuery({queryKey:['documentos-despesa',projectId,purchaseId||null],queryFn:()=>api<{documentos:PaymentDocument[]}>(endpoint),enabled:Boolean(purchaseId)})
  const reset=()=>{setTitle('');setUrl('');setFile(null);setError('')}
  const save=useMutation({mutationFn:(form:FormData)=>api(endpoint,{method:'POST',body:form}),onSuccess:()=>{reset();void client.invalidateQueries({queryKey:['documentos-despesa',projectId,purchaseId||null]});void client.invalidateQueries({queryKey:['despesas',projectId]})}})
  const remove=useMutation({mutationFn:(id:number)=>api(`${endpoint}/${id}`,{method:'DELETE'}),onSuccess:()=>{void client.invalidateQueries({queryKey:['documentos-despesa',projectId,purchaseId||null]});void client.invalidateQueries({queryKey:['despesas',projectId]})}})
  const addDocument=()=>{const normalizedTitle=title.trim();if(!normalizedTitle){setError('Informe o título do documento.');return}if(source==='LINK'&&!url.trim()){setError('Informe a URL do documento.');return}if(source==='ARQUIVO'&&!file){setError('Selecione um arquivo.');return}const draft:PaymentDocumentDraft={id:crypto.randomUUID(),titulo:normalizedTitle,source,url:source==='LINK'?url.trim():null,file:source==='ARQUIVO'?file:null};if(purchaseId)save.mutate(paymentDocumentForm(draft));else{onDraftsChange?.([...drafts,draft]);reset()}}
  const openUrl=(document:PaymentDocument)=>document.url||`${endpoint}/${document.id}/arquivo`;const visible=purchaseId?documents.data?.documentos||[]:drafts
  return <section className="payment-resource-panel"><header><div><Paperclip/><strong>Documentos da despesa</strong><span>{visible.length}</span></div></header>{documents.error&&<ErrorNotice message={documents.error.message}/>} {save.error&&<ErrorNotice message={save.error.message}/>}<div className="payment-document-list">{purchaseId?(visible as PaymentDocument[]).map(document=><div className="payment-document-box" key={document.id}><a className="payment-document-item" href={openUrl(document)} target="_blank" rel="noopener noreferrer" title={document.titulo} aria-label={`Abrir ${document.titulo}`}><FileText/><span>{document.titulo}</span><ExternalLink/></a>{editable&&<button className="danger" type="button" title="Excluir documento" aria-label={`Excluir ${document.titulo}`} onClick={()=>{if(confirm('Excluir este documento?'))remove.mutate(document.id)}}><Trash2/></button>}</div>):drafts.map(document=><div className="payment-document-box draft" key={document.id}><span title={document.titulo}>{document.titulo}</span><button className="danger" type="button" aria-label={`Remover ${document.titulo}`} onClick={()=>onDraftsChange?.(drafts.filter(current=>current.id!==document.id))}><Trash2/></button></div>)}</div>{editable&&<><div className="resource-inline-form"><input value={title} onChange={event=>setTitle(event.target.value)} placeholder="Título do documento"/><select value={source} onChange={event=>setSource(event.target.value as 'LINK'|'ARQUIVO')}><option value="LINK">Link</option><option value="ARQUIVO">Arquivo</option></select>{source==='LINK'?<input value={url} type="url" onChange={event=>setUrl(event.target.value)} placeholder="https://…"/>:<input type="file" onChange={event=>setFile(event.target.files?.[0]||null)} accept="application/pdf,image/jpeg,image/png,image/webp"/>}<button type="button" className="app-button" disabled={save.isPending} onClick={addDocument}><Plus/>Adicionar</button></div>{error&&<small className="payment-document-form-error">{error}</small>}</>}</section>
}

function PurchaseDocuments(props:{projectId:string;purchaseId?:number;itemId?:number;purchases:Purchase[];editable?:boolean;drafts?:PaymentDocumentDraft[];onDraftsChange?:(documents:PaymentDocumentDraft[])=>void}) { return <LegacyPurchaseDocuments {...props}/> }

function LegacyItemContext({item}:{item:PurchaseItem}) {
  const fields=[
    ['Etapa',item.etapa],['Status',item.status?PAYMENT_STATUSES.find(option=>option.value===item.status)?.label:null],
    ['Fornecedor',item.fornecedor],['Nome do funcionário',item.nome_contato_fornecedor],['Contato',item.contato_fornecedor],
    ['Forma de pagamento',item.forma_pagamento],['Data do pagamento',item.data_pagamento?formatDate(item.data_pagamento):null],
    ['Data de agendamento',item.data_agendamento?formatDate(item.data_agendamento):null],['Data de entrega',item.data_entrega?formatDate(item.data_entrega):null],
  ].filter((field):field is [string,string]=>Boolean(field[1]))
  if(!fields.length)return null
  return <aside className="legacy-item-context span-2"><header><strong>Dados preservados do pagamento anterior</strong><small>Informações somente para consulta durante a organização manual.</small></header><div>{fields.map(([label,value])=><p key={label}><span>{label}</span><strong>{value}</strong></p>)}</div></aside>
}

// Mantido apenas como referencia de compatibilidade durante a transicao do formulario.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyItemDialog({projectId,context,purchases,onClose}:{projectId:string;context:{purchaseId:number|null;item?:PurchaseItem};purchases:Purchase[];onClose:()=>void}){
  const client=useQueryClient();const item=context.item;const[links,setLinks]=useState<QuoteLinkDraft[]>([]);const[quantity,setQuantity]=useState(item?.quantidade||'');const[unitValue,setUnitValue]=useState(()=>formatCurrencyInput(item?.valor_unitario));const total=quantity&&currencyNumber(unitValue)!==null?Number(quantity)*Number(currencyNumber(unitValue)):null
  const save=useMutation({mutationFn:(payload:Record<string,unknown>)=>api(item?`/projetos/${projectId}/despesas/itens/${item.id}`:`/projetos/${projectId}/despesas/compras/${context.purchaseId}/itens`,{method:item?'PUT':'POST',...jsonBody(payload)}),onSuccess:()=>{void client.invalidateQueries({queryKey:['compras',projectId]});onClose()}})
  const remove=useMutation({mutationFn:()=>api(`/projetos/${projectId}/despesas/itens/${item!.id}`,{method:'DELETE'}),onSuccess:()=>{void client.invalidateQueries({queryKey:['compras',projectId]});onClose()}})
  const submit=(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();const form=new FormData(event.currentTarget);save.mutate({descricao:form.get('descricao'),quantidade:form.get('quantidade')||null,unidade:form.get('unidade')||null,observacao:form.get('observacao')||null,valor_unitario:form.get('valor_unitario')||null,ordem:item?.ordem??0,...(!item?{links_cotacao:links.map(link=>link.url)}:{})})}
  return <div className="dialog-backdrop"><section className="dialog large payment-dialog"><header><div><small>ITEM DA COMPRA</small><h2>{item?'Editar item':'Novo item'}</h2></div><button onClick={onClose}><X/></button></header><form onSubmit={submit}>{save.error&&<ErrorNotice message={save.error.message}/>} {item&&context.purchaseId===null&&<LegacyItemContext item={item}/>}<label className="field span-2"><span>Descrição</span><input name="descricao" required defaultValue={item?.descricao||''}/></label><label className="field"><span>Quantidade</span><input name="quantidade" type="number" min="0.001" step="0.001" value={quantity} onChange={event=>setQuantity(event.target.value)}/></label><label className="field"><span>Unidade</span><input name="unidade" defaultValue={item?.unidade||''}/></label><label className="field"><span>Valor unitário</span><input name="valor_unitario" type="number" min="0" step="0.01" value={unitValue} onChange={event=>setUnitValue(event.target.value)}/></label><label className="field"><span>Valor total calculado</span><input readOnly value={total===null?'—':formatMoney(total)}/></label><label className="field span-2"><span>Observações</span><textarea name="observacao" rows={4} defaultValue={item?.observacao||''}/></label><label className="field compact"><span>Ordem</span><input name="ordem" type="number" min="0" defaultValue={item?.ordem||0}/></label><div className="span-2"><PaymentLinks key={item?.id||'new'} projectId={projectId} item={item} drafts={links} onDraftsChange={setLinks} editable/></div>{item&&<div className="span-2"><PurchaseDocuments projectId={projectId} itemId={item.id} purchases={purchases} editable/></div>}<footer className="form-actions span-2">{item&&<button type="button" className="app-button danger-action" onClick={()=>confirm('Excluir este item?')&&remove.mutate()}><Trash2/>Excluir</button>}<button type="button" className="app-button" onClick={onClose}>Cancelar</button><button className="app-button primary" disabled={save.isPending}>{save.isPending?'Salvando…':'Salvar item'}</button></footer></form></section></div>
}

function ItemDialog({projectId,context,purchases,onClose}:{projectId:string;context:{purchaseId:number|null;item?:PurchaseItem};purchases:Purchase[];onClose:()=>void}) {
  const client=useQueryClient()
  const item=context.item
  const [links,setLinks]=useState<QuoteLinkDraft[]>([])
  const [quantity,setQuantity]=useState(item?.quantidade||'')
  const [unitValue,setUnitValue]=useState(()=>formatStoredUnitValue(item?.valor_unitario))
  const [discountValue,setDiscountValue]=useState(()=>formatStoredMoney(item?.valor_desconto))
  const [totalValue,setTotalValue]=useState(()=>formatStoredMoney(item?.valor_total))
  const [manualTotal,setManualTotal]=useState(Boolean(item?.valor_total_manual))
  const calculatedTotal=(nextQuantity=quantity,nextUnitValue=unitValue,nextDiscountValue=discountValue)=>{
    const unitAmount=currencyNumber(nextUnitValue);const discountAmount=moneyInputNumber(nextDiscountValue)||0
    return nextQuantity&&unitAmount!==null?Math.max(0,Number((Number(nextQuantity)*unitAmount-discountAmount).toFixed(2))):null
  }
  const updateCalculatedTotal=(nextQuantity=quantity,nextUnitValue=unitValue,nextDiscountValue=discountValue)=>{
    const nextTotal=calculatedTotal(nextQuantity,nextUnitValue,nextDiscountValue)
    setManualTotal(false);setTotalValue(nextTotal===null?'':formatStoredMoney(nextTotal))
  }
  const save=useMutation({
    mutationFn:(payload:Record<string,unknown>)=>api(item?`/projetos/${projectId}/despesas/itens/${item.id}`:`/projetos/${projectId}/despesas/despesas/${context.purchaseId}/itens`,{method:item?'PUT':'POST',...jsonBody(payload)}),
    onSuccess:()=>{void client.invalidateQueries({queryKey:['despesas',projectId]});onClose()},
  })
  const remove=useMutation({
    mutationFn:()=>api(`/projetos/${projectId}/despesas/itens/${item!.id}`,{method:'DELETE'}),
    onSuccess:()=>{void client.invalidateQueries({queryKey:['despesas',projectId]});onClose()},
  })
  const [moveTarget,setMoveTarget]=useState('')
  const [showMove,setShowMove]=useState(false)
  const move=useMutation({
    mutationFn:()=>api(`/projetos/${projectId}/despesas/itens/${item!.id}/mover`,{method:'POST',...jsonBody({despesa_id:Number(moveTarget)})}),
    onSuccess:()=>{void client.invalidateQueries({queryKey:['despesas',projectId]});onClose()},
  })
  const submit=(event:FormEvent<HTMLFormElement>)=>{
    event.preventDefault()
    const form=new FormData(event.currentTarget)
    save.mutate({
      descricao:form.get('descricao'), quantidade:form.get('quantidade')||null,
      unidade:form.get('unidade')||null, observacao:form.get('observacao')||null,
      valor_unitario:form.get('valor_unitario')||null, valor_desconto:form.get('valor_desconto')||null,
      valor_total:manualTotal?form.get('valor_total')||null:null, ordem:item?.ordem??0,
      ...(!item?{links_cotacao:links.map(link=>link.url)}:{}),
    })
  }
  return <div className="dialog-backdrop"><section className="dialog large payment-dialog"><header><div><small>ITEM DA COMPRA</small><h2>{item?'Editar item':'Novo item'}</h2></div><button onClick={onClose}><X/></button></header><form onSubmit={submit}>
    {save.error&&<ErrorNotice message={save.error.message}/>}
    {item&&context.purchaseId===null&&<LegacyItemContext item={item}/>}
    <label className="field span-2"><span>Descrição</span><input name="descricao" required defaultValue={item?.descricao||''}/></label>
    <label className="field"><span>Quantidade</span><input name="quantidade" type="number" min="0.001" step="0.001" value={quantity} onChange={event=>{setQuantity(event.target.value);updateCalculatedTotal(event.target.value)}}/></label>
    <label className="field"><span>Unidade</span><input name="unidade" defaultValue={item?.unidade||''}/></label>
    <label className="field"><span>Valor unitário</span><div className="currency-input"><span>R$</span><input inputMode="numeric" value={unitValue} onChange={event=>{const nextValue=formatCurrencyInput(event.target.value);setUnitValue(nextValue);updateCalculatedTotal(quantity,nextValue)}} placeholder="0,0000"/></div><input name="valor_unitario" type="hidden" value={currencyInputValue(unitValue)}/></label>
    <label className="field discount-field"><span>Valor desconto</span><div className="currency-input"><span>R$</span><input inputMode="numeric" value={discountValue} onChange={event=>{const nextValue=formatMoneyInput(event.target.value);setDiscountValue(nextValue);updateCalculatedTotal(quantity,unitValue,nextValue)}} placeholder="0,00"/></div><input name="valor_desconto" type="hidden" value={moneyInputValue(discountValue)}/></label>
    <label className="field"><span>Valor total</span><div className="currency-input"><span>R$</span><input inputMode="numeric" value={totalValue} onChange={event=>{const nextValue=formatMoneyInput(event.target.value);setTotalValue(nextValue);setManualTotal(Boolean(nextValue));const amount=moneyInputNumber(nextValue);const discount=moneyInputNumber(discountValue)||0;if(amount!==null&&Number(quantity)>0)setUnitValue(formatStoredUnitValue((amount+discount)/Number(quantity)))}} placeholder="0,00"/></div><input name="valor_total" type="hidden" value={moneyInputValue(totalValue)}/></label>
    <label className="field span-2"><span>Observações</span><textarea name="observacao" rows={4} defaultValue={item?.observacao||''}/></label>
    <div className="span-2"><PaymentLinks key={item?.id||'new'} projectId={projectId} item={item} drafts={links} onDraftsChange={setLinks} editable/></div>
    {item&&context.purchaseId!==null&&showMove&&<section className="item-move-panel span-2"><strong>Mover item para outra despesa</strong><div><select value={moveTarget} onChange={event=>setMoveTarget(event.target.value)}><option value="">Selecione a despesa de destino</option>{purchases.filter(purchase=>purchase.id!==context.purchaseId).map(purchase=><option key={purchase.id} value={purchase.id}>{purchase.descricao}</option>)}</select><button type="button" className="app-button" disabled={!moveTarget||move.isPending} onClick={()=>confirm('Mover este item para a despesa selecionada?')&&move.mutate()}><MoveRight/>Confirmar movimentação</button></div>{move.error&&<ErrorNotice message={move.error.message}/>}</section>}
    <footer className="form-actions span-2">{item&&<button type="button" className="app-button danger-action" onClick={()=>confirm('Excluir este item?')&&remove.mutate()}><Trash2/>Excluir</button>}{item&&context.purchaseId!==null&&<button type="button" className="app-button" onClick={()=>setShowMove(current=>!current)}><MoveRight/>Mover item</button>}<button type="button" className="app-button" onClick={onClose}>Cancelar</button><button className="app-button primary" disabled={save.isPending}>{save.isPending?'Salvando…':'Salvar item'}</button></footer>
  </form></section></div>
}

export function PaymentsPage(){
  const{projetoId}=useParams();const projectId=projetoId!;const{can}=useProjectAccess();const client=useQueryClient();const endpoint=`/projetos/${projectId}/despesas`
  const[status,setStatus]=useState('');const[stageFilter,setStageFilter]=useState('');const[search,setSearch]=useState('');const[expanded,setExpanded]=useState<number|null>(null);const[expandedItem,setExpandedItem]=useState<number|null>(null);const[editingPurchase,setEditingPurchase]=useState<Purchase|'new'|null>(null);const[editingItem,setEditingItem]=useState<{purchaseId:number|null;item?:PurchaseItem}|null>(null);const[moving,setMoving]=useState(false);const[selectedItems,setSelectedItems]=useState<number[]>([]);const[targetPurchase,setTargetPurchase]=useState('');const[importing,setImporting]=useState(false);const[documentDrafts,setDocumentDrafts]=useState<PaymentDocumentDraft[]>([]);const[uploadError,setUploadError]=useState('')
  const purchases=useQuery({queryKey:['despesas',projectId,status,stageFilter,search],queryFn:()=>api<PurchaseList>(`${endpoint}/despesas?status=${status}&etapaId=${stageFilter}&busca=${encodeURIComponent(search)}`)})
  const stages=useQuery({queryKey:['etapas',projectId],queryFn:()=>api<{etapas:StageOption[]}>(`${endpoint}/etapas`)})
  const suppliers=useQuery({queryKey:['fornecedores-pagamentos',projectId],queryFn:()=>api<{fornecedores:Supplier[]}>(`${endpoint}/fornecedores`)})
  const purchaseRows=purchases.data?.despesas||purchases.data?.compras||[];const orphanItems=purchases.data?.itens_orfaos||[]
  const purchaseSort=useSortableData(purchaseRows,'status','asc','last',(left,right)=>PAYMENT_STATUSES.findIndex(option=>option.value===left.status)-PAYMENT_STATUSES.findIndex(option=>option.value===right.status))
  const closePurchase=()=>{setEditingPurchase(null);setDocumentDrafts([]);setUploadError('')}
  const savePurchase=useMutation({mutationFn:({id,payload}:{id?:number;payload:Record<string,unknown>})=>api<{despesa?:{id:number}}>(`${endpoint}/despesas${id?`/${id}`:''}`,{method:id?'PUT':'POST',...jsonBody(payload)}),onSuccess:()=>{void client.invalidateQueries({queryKey:['despesas',projectId]});void client.invalidateQueries({queryKey:['fornecedores-pagamentos',projectId]})}})
  const deletePurchase=useMutation({mutationFn:(id:number)=>api(`${endpoint}/despesas/${id}`,{method:'DELETE'}),onSuccess:()=>{closePurchase();void client.invalidateQueries({queryKey:['despesas',projectId]})}})
  const deleteItem=useMutation({mutationFn:(id:number)=>api(`${endpoint}/itens/${id}`,{method:'DELETE'}),onSuccess:()=>void client.invalidateQueries({queryKey:['despesas',projectId]})})
  const statusUpdate=useMutation({mutationFn:({id,status}:{id:number;status:PaymentStatus})=>api(`${endpoint}/despesas/${id}/status`,{method:'PATCH',...jsonBody({status})}),onSuccess:()=>void client.invalidateQueries({queryKey:['despesas',projectId]})})
  const moveItems=useMutation({mutationFn:()=>api(`${endpoint}/itens/mover`,{method:'POST',...jsonBody({item_ids:selectedItems,despesa_id:Number(targetPurchase)})}),onSuccess:()=>{setMoving(false);setSelectedItems([]);setTargetPurchase('');void client.invalidateQueries({queryKey:['despesas',projectId]})}})
  const supplierNames=useMemo(()=>suppliers.data?.fornecedores||[],[suppliers.data]);const chooseSupplier=(name:string)=>supplierNames.find(item=>item.fornecedor===name)
  const submitPurchase=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();setUploadError('');const form=new FormData(event.currentTarget);const payload={descricao:form.get('descricao'),etapa_id:form.get('etapa_id')||null,status:form.get('status'),observacao:form.get('observacao')||null,valor_desconto:form.get('valor_desconto')||null,fornecedor:form.get('fornecedor')||null,nome_contato_fornecedor:form.get('nome_contato_fornecedor')||null,contato_fornecedor:form.get('contato_fornecedor')||null,data_pagamento:form.get('data_pagamento')||null,forma_pagamento:form.get('forma_pagamento')||null,numero_nota_fiscal:form.get('numero_nota_fiscal')||null,data_emissao:form.get('data_emissao')||null,data_agendamento:form.get('data_agendamento')||null,data_entrega:form.get('data_entrega')||null,ordem:form.get('ordem')||0};try{const result=await savePurchase.mutateAsync({id:editingPurchase==='new'?undefined:editingPurchase?.id,payload});if(editingPurchase==='new'&&documentDrafts.length){const purchaseId=Number(result.despesa?.id);try{for(const document of documentDrafts)await api(`${endpoint}/despesas/${purchaseId}/documentos`,{method:'POST',body:paymentDocumentForm(document)})}catch{setUploadError('A despesa foi criada, mas um documento não pôde ser enviado. Abra a despesa e tente novamente.');setDocumentDrafts([]);return}}closePurchase()}catch{return}}
  return <div><PageHeader eyebrow="FINANCEIRO" title="Despesas" description="Materiais, serviços, documentos, cotações e pagamentos organizados por despesa." action={<div className="heading-actions">{can('pagamentos.exportar')&&<ExportAction title="Despesas" pdfUrl={`/api${endpoint}/relatorio.pdf`} xlsxUrl={`/api${endpoint}/relatorio.xlsx`}/>} {can('pagamentos.inserir')&&<><button className="app-button" onClick={()=>setImporting(true)}><Upload/>Importar itens</button>{orphanItems.length>0&&<button className="app-button" onClick={()=>setMoving(true)}><MoveRight/>Mover itens</button>}<AddButton onClick={()=>{setDocumentDrafts([]);setEditingPurchase('new')}}>Nova Despesa</AddButton></>}</div>}/>
    <section className="table-toolbar payments-toolbar" aria-label="Filtros de despesas"><label className="search-field"><span>Pesquisar</span><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Descrição ou fornecedor"/></label><label className="compact-field"><span>Etapa</span><select className="expense-stage-select" value={stageFilter} style={stageBadgeStyle(stages.data?.etapas.find(stage=>String(stage.id)===stageFilter)?.cor)} onChange={event=>setStageFilter(event.target.value)}><option value="">Todas</option>{stages.data?.etapas.filter(stage=>stage.parent_id===null).map(stage=><option key={stage.id} value={stage.id}>{formatStageOption(stage,stages.data?.etapas||[])}</option>)}</select></label><label className="compact-field"><span>Status</span><select value={status} className={`expense-status-select ${status?paymentStatusClass(status):''}`} onChange={event=>setStatus(event.target.value)}><option value="">Todos</option>{PAYMENT_STATUSES.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label></section>
    {purchases.error&&<ErrorNotice message={purchases.error.message}/>} {!purchaseRows.length&&!orphanItems.length?<EmptyState title="Nenhuma despesa encontrada" description="Cadastre uma despesa e inclua seus itens."/>:<>{purchaseRows.length>0&&<section className="crud-table-frame purchase-grid">
      <div className="table-summary"><strong>{purchaseRows.length}</strong> despesas</div>
      <table className="data-table purchase-table">
        <thead><tr><th/><SortableHeader<Purchase> label="Descrição" column="descricao" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><SortableHeader<Purchase> label="Etapa" column="etapa" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><SortableHeader<Purchase> label="Documento" column="documento" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><SortableHeader<Purchase> label="Status" column="status" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><SortableHeader<Purchase> label="Fornecedor" column="fornecedor" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><SortableHeader<Purchase> label="Data do pagamento" column="data_pagamento" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><SortableHeader<Purchase> label="Valor total" column="valor_total" className="money-column" activeColumn={purchaseSort.sort.key} direction={purchaseSort.sort.direction} onSort={purchaseSort.toggle}/><th>AÇÕES</th></tr></thead>
        <tbody>{purchaseSort.sorted.map(purchase=><Fragment key={purchase.id}>
          <tr className={`purchase-row status-colored-row ${paymentStatusClass(purchase.status)}`} onClick={()=>setExpanded(expanded===purchase.id?null:purchase.id)}>
            <td><button className="expand-button" aria-label="Expandir despesa">{expanded===purchase.id?<ChevronDown/>:<ChevronRight/>}</button></td>
            <td><strong>{purchase.descricao}</strong></td>
            <td>{purchase.etapa&&purchase.etapa_cor?<span className="payment-stage-badge" style={stageBadgeStyle(purchase.etapa_cor)}>{purchase.etapa}</span>:purchase.etapa||'—'}</td>
            <td><span className={`purchase-document-kind ${purchase.documento==='Nota Fiscal'?'invoice':''}`}>{purchase.documento}</span></td>
            <td><select className={`payment-status-select ${paymentStatusClass(purchase.status)}`} value={purchase.status} onClick={event=>event.stopPropagation()} onChange={event=>statusUpdate.mutate({id:purchase.id,status:event.target.value as PaymentStatus})}>{PAYMENT_STATUSES.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></td>
            <td>{purchase.fornecedor||'—'}</td><td>{formatDate(purchase.data_pagamento)}</td>
            <td className="money-column"><strong>{formatMoney(purchase.valor_total)}</strong></td>
            <td className="row-actions">{can('pagamentos.atualizar')&&<button title="Editar despesa" onClick={event=>{event.stopPropagation();setDocumentDrafts([]);setEditingPurchase(purchase)}}><Pencil/></button>}{can('pagamentos.excluir')&&<button className="danger" title="Excluir despesa" onClick={event=>{event.stopPropagation();if(confirm('Excluir esta despesa? Os itens voltarão para Itens sem Despesa.'))deletePurchase.mutate(purchase.id)}}><Trash2/></button>}</td>
          </tr>
          {expanded===purchase.id&&<tr className="purchase-expanded-row"><td colSpan={9}><section className="purchase-items-panel">
            <header><div><strong>Itens da Compra</strong><small>{purchase.itens.length} {purchase.itens.length===1?'item':'itens'}</small></div>{can('pagamentos.inserir')&&<button className="app-button" onClick={()=>setEditingItem({purchaseId:purchase.id})}><Plus/>Adicionar item</button>}</header>
            {purchase.itens.length===0?<p className="purchase-empty-items">Nenhum item vinculado a esta despesa.</p>:<table className="purchase-items-table"><thead><tr><th/><th>Descrição</th><th>Quantidade</th><th>Unidade</th><th>Valor unitário</th><th>Valor desconto</th><th>Valor total</th><th>Ações</th></tr></thead><tbody>{purchase.itens.map(item=><Fragment key={item.id}><tr><td><button className="expand-button" onClick={()=>setExpandedItem(expandedItem===item.id?null:item.id)}>{expandedItem===item.id?<ChevronDown/>:<ChevronRight/>}</button></td><td><strong>{item.descricao}</strong></td><td>{item.quantidade?formatQuantity(item.quantidade):'—'}</td><td>{item.unidade||'—'}</td><td>{item.valor_unitario===null?'—':formatMoney(item.valor_unitario)}</td><td className="expense-discount">{item.valor_desconto===null?'—':formatMoney(item.valor_desconto)}</td><td><strong>{item.valor_total===null?'—':formatMoney(item.valor_total)}</strong></td><td className="row-actions"><button title="Editar item" onClick={()=>setEditingItem({purchaseId:purchase.id,item})}><Pencil/></button>{can('pagamentos.excluir')&&<button className="danger" title="Excluir item" onClick={()=>{if(confirm('Excluir este item?'))deleteItem.mutate(item.id)}}><Trash2/></button>}</td></tr>{expandedItem===item.id&&<tr className="purchase-item-details"><td colSpan={8}><div className="payment-expanded item-observation-expanded"><p><strong>Observações:</strong> <span className="preserve-lines">{item.observacao||'—'}</span></p></div></td></tr>}</Fragment>)}</tbody></table>}
            <footer><strong>Total da Compra</strong><span>{formatMoney(purchase.valor_total)}</span></footer>
            <PurchaseDocuments projectId={projectId} purchaseId={purchase.id} purchases={purchaseRows}/>
          </section></td></tr>}
        </Fragment>)}</tbody>
      </table>
    </section>}{orphanItems.length>0&&<section className="orphan-items-panel"><header><div><span>TRANSIÇÃO</span><h2>Itens sem Compra</h2><p>Registros anteriores preservados. Selecione “Mover itens” para organizá-los em uma Compra.</p></div><button className="app-button" onClick={()=>setMoving(true)}><MoveRight/>Mover itens</button></header><div>{orphanItems.map(item=><button key={item.id} type="button" onClick={()=>setEditingItem({purchaseId:null,item})}><span>{item.descricao}</span><strong>{item.valor_total===null?'—':formatMoney(item.valor_total)}</strong><ChevronRight/></button>)}</div></section>}</>}
    {editingPurchase&&<PurchaseDialog projectId={projectId} purchase={editingPurchase} purchases={purchaseRows} stages={stages.data?.etapas||[]} suppliers={supplierNames} documents={documentDrafts} setDocuments={setDocumentDrafts} uploadError={uploadError} save={savePurchase} submit={submitPurchase} onClose={closePurchase} onSupplier={chooseSupplier}/>} {editingItem&&<ItemDialog projectId={projectId} context={editingItem} purchases={purchaseRows} onClose={()=>setEditingItem(null)}/>} {moving&&<MoveItemsDialog items={orphanItems} purchases={purchaseRows} selected={selectedItems} setSelected={setSelectedItems} target={targetPurchase} setTarget={setTargetPurchase} mutation={moveItems} onClose={()=>setMoving(false)}/>} {importing&&<ImportDialog endpoint={endpoint} entityName="itens de compra" onClose={()=>setImporting(false)} onComplete={()=>{setImporting(false);void client.invalidateQueries({queryKey:['compras',projectId]})}}/>}
  </div>
}

type PurchaseMutation={error:Error|null;isPending:boolean}
// Mantido apenas como referencia de compatibilidade durante a transicao do formulario.
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function LegacyPurchaseDialog({projectId,purchase,purchases,stages,suppliers,documents,setDocuments,uploadError,save,submit,onClose,onSupplier}:{projectId:string;purchase:Purchase|'new';purchases:Purchase[];stages:StageOption[];suppliers:Supplier[];documents:PaymentDocumentDraft[];setDocuments:(documents:PaymentDocumentDraft[])=>void;uploadError:string;save:PurchaseMutation;submit:(event:FormEvent<HTMLFormElement>)=>void;onClose:()=>void;onSupplier:(name:string)=>Supplier|undefined}){
  return <div className="dialog-backdrop"><section className="dialog large payment-dialog purchase-dialog"><header><div><small>COMPRA</small><h2>{purchase==='new'?'Nova Compra':'Editar Compra'}</h2></div><button onClick={onClose}><X/></button></header><form onSubmit={submit}>{save.error&&<ErrorNotice message={save.error.message}/>} {uploadError&&<ErrorNotice message={uploadError}/>}<section className="purchase-form-section span-2"><h3>Compra</h3><label className="field span-2"><span>Descrição</span><input name="descricao" required defaultValue={purchase==='new'?'':purchase.descricao}/></label><label className="field"><span>Etapa</span><select name="etapa_id" defaultValue={purchase==='new'?'':purchase.etapa_id||''}><option value="">Sem etapa</option>{stages.map(stage=><option key={stage.id} value={stage.id}>{formatStageOption(stage,stages)}</option>)}</select></label><label className="field"><span>Status</span><select name="status" defaultValue={purchase==='new'?'PENDENTE':purchase.status}>{PAYMENT_STATUSES.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label></section><section className="purchase-form-section span-2"><h3>Fornecedor</h3><label className="field span-2"><span>Fornecedor</span><input name="fornecedor" list="purchase-suppliers" defaultValue={purchase==='new'?'':purchase.fornecedor||''} onBlur={event=>{const selected=onSupplier(event.currentTarget.value);const form=event.currentTarget.form;if(!selected||!form)return;const employee=form.elements.namedItem('nome_contato_fornecedor') as HTMLInputElement;const contact=form.elements.namedItem('contato_fornecedor') as HTMLInputElement;if(!employee.value)employee.value=selected.nome_contato_fornecedor||'';if(!contact.value)contact.value=selected.contato_fornecedor||''}}/><datalist id="purchase-suppliers">{suppliers.map(item=><option key={item.fornecedor} value={item.fornecedor}/>)}</datalist></label><label className="field"><span>Nome do Funcionário</span><input name="nome_contato_fornecedor" defaultValue={purchase==='new'?'':purchase.nome_contato_fornecedor||''}/></label><label className="field"><span>Contato do fornecedor</span><input name="contato_fornecedor" defaultValue={purchase==='new'?'':purchase.contato_fornecedor||''}/></label></section><section className="purchase-form-section span-2"><h3>Pagamento</h3><label className="field"><span>Data do pagamento</span><input name="data_pagamento" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_pagamento)}/></label><label className="field"><span>Forma de pagamento</span><select name="forma_pagamento" defaultValue={purchase==='new'?'':purchase.forma_pagamento||''}><option value="">Não definida</option><option value="PIX">PIX</option><option value="CARTAO">Cartão</option><option value="DINHEIRO">Dinheiro</option><option value="BOLETO">Boleto</option><option value="TRANSFERENCIA">Transferência</option><option value="OUTRO">Outro</option></select></label></section><section className="purchase-form-section span-2"><h3>Nota Fiscal</h3><label className="field span-2"><span>Número da Nota Fiscal</span><input name="numero_nota_fiscal" defaultValue={purchase==='new'?'':purchase.numero_nota_fiscal||''} placeholder="Vazio identifica a compra como Orçamento"/></label><label className="field"><span>Data de emissão</span><input name="data_emissao" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_emissao)}/></label><label className="field"><span>Data de agendamento</span><input name="data_agendamento" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_agendamento)}/></label><label className="field"><span>Data de entrega</span><input name="data_entrega" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_entrega)}/></label><label className="field compact"><span>Ordem</span><input name="ordem" type="number" min="0" defaultValue={purchase==='new'?0:purchase.ordem}/></label></section><div className="span-2"><PurchaseDocuments projectId={projectId} purchaseId={purchase==='new'?undefined:purchase.id} purchases={purchases} editable drafts={purchase==='new'?documents:undefined} onDraftsChange={purchase==='new'?setDocuments:undefined}/></div><footer className="form-actions span-2"><button type="button" className="app-button" onClick={onClose}>Cancelar</button><button className="app-button primary" disabled={save.isPending}>{save.isPending?'Salvando…':'Salvar Compra'}</button></footer></form></section></div>
}

function PurchaseDialog({projectId,purchase,purchases,stages,suppliers,documents,setDocuments,uploadError,save,submit,onClose,onSupplier}:{projectId:string;purchase:Purchase|'new';purchases:Purchase[];stages:StageOption[];suppliers:Supplier[];documents:PaymentDocumentDraft[];setDocuments:(documents:PaymentDocumentDraft[])=>void;uploadError:string;save:PurchaseMutation;submit:(event:FormEvent<HTMLFormElement>)=>void;onClose:()=>void;onSupplier:(name:string)=>Supplier|undefined}) {
  const [contact,setContact]=useState(()=>formatSupplierPhone(purchase==='new'?'':purchase.contato_fornecedor))
  const [selectedStageId,setSelectedStageId]=useState(()=>purchase==='new'?'':String(purchase.etapa_id||''))
  const [selectedStatus,setSelectedStatus]=useState<PaymentStatus>(()=>purchase==='new'?'PENDENTE':purchase.status)
  const chooseSupplier=(event:FocusEvent<HTMLInputElement>)=>{
    const selected=onSupplier(event.currentTarget.value)
    const form=event.currentTarget.form
    if(!selected||!form)return
    const employee=form.elements.namedItem('nome_contato_fornecedor') as HTMLInputElement
    if(!employee.value) employee.value=selected.nome_contato_fornecedor||''
    if(!localPhoneDigits(contact)) setContact(formatSupplierPhone(selected.contato_fornecedor))
  }
  return <div className="dialog-backdrop"><section className="dialog large payment-dialog purchase-dialog"><header><div><small>DESPESA</small><h2>{purchase==='new'?'Nova Despesa':'Editar Despesa'}</h2></div><button onClick={onClose}><X/></button></header><form onSubmit={submit}><input name="ordem" type="hidden" value={purchase==='new'?0:purchase.ordem}/>
    {save.error&&<ErrorNotice message={save.error.message}/>} {uploadError&&<ErrorNotice message={uploadError}/>}
    <section className="purchase-form-section span-2"><h3>Despesa</h3>
      <label className="field span-2"><span>Descrição</span><input name="descricao" required defaultValue={purchase==='new'?'':purchase.descricao}/></label>
      <label className="field"><span>Etapa</span><select name="etapa_id" className="expense-stage-select" value={selectedStageId} style={stageBadgeStyle(stages.find(stage=>String(stage.id)===selectedStageId)?.cor)} onChange={event=>setSelectedStageId(event.target.value)}><option value="">Sem etapa</option>{stages.filter(stage=>stage.parent_id===null).map(stage=><option key={stage.id} value={stage.id}>{formatStageOption(stage,stages)}</option>)}</select></label>
      <label className="field"><span>Status</span><select name="status" value={selectedStatus} className={`expense-status-select ${paymentStatusClass(selectedStatus)}`} onChange={event=>setSelectedStatus(event.target.value as PaymentStatus)}>{PAYMENT_STATUSES.map(option=><option key={option.value} value={option.value}>{option.label}</option>)}</select></label>
      <label className="field span-2"><span>Observações</span><textarea name="observacao" rows={3} defaultValue={purchase==='new'?'':purchase.observacao||''}/></label>
    </section>
    <section className="purchase-form-section span-2"><h3>Fornecedor</h3>
      <label className="field span-2"><span>Fornecedor</span><input name="fornecedor" list="purchase-suppliers" defaultValue={purchase==='new'?'':purchase.fornecedor||''} onBlur={chooseSupplier}/><datalist id="purchase-suppliers">{suppliers.map(item=><option key={item.fornecedor} value={item.fornecedor}/>)}</datalist></label>
      <label className="field"><span>Nome do Funcionário</span><input name="nome_contato_fornecedor" defaultValue={purchase==='new'?'':purchase.nome_contato_fornecedor||''}/></label>
      <label className="field"><span>Contato do fornecedor</span><input name="contato_fornecedor" inputMode="tel" autoComplete="tel" value={contact} onChange={event=>setContact(formatSupplierPhone(event.target.value))} placeholder="+55 (51) 99999-9999"/></label>
    </section>
    <section className="purchase-form-section span-2"><h3>Pagamento</h3>
      <label className="field"><span>Data do pagamento</span><input name="data_pagamento" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_pagamento)}/></label>
      <label className="field"><span>Forma de pagamento</span><select name="forma_pagamento" defaultValue={purchase==='new'?'':purchase.forma_pagamento||''}><option value="">Não definida</option><option value="PIX">PIX</option><option value="CARTAO">Cartão</option><option value="DINHEIRO">Dinheiro</option><option value="BOLETO">Boleto</option><option value="TRANSFERENCIA">Transferência</option><option value="OUTRO">Outro</option></select></label>
      <label className="field discount-field"><span>Valor desconto</span><div className="currency-input"><span>R$</span><input name="valor_desconto" inputMode="decimal" defaultValue={purchase==='new'?'':formatStoredMoney(purchase.valor_desconto)} placeholder="0,00"/></div></label>
      <label className="field"><span>Valor total</span><div className="currency-input"><span>R$</span><input readOnly value={purchase==='new'?'0,00':formatStoredMoney(purchase.valor_total)}/></div></label>
    </section>
    <section className="purchase-form-section span-2"><h3>Nota Fiscal</h3>
      <label className="field"><span>Número da NF</span><input name="numero_nota_fiscal" defaultValue={purchase==='new'?'':purchase.numero_nota_fiscal||''} placeholder="Vazio identifica como Orçamento"/></label>
      <label className="field"><span>Data de emissão</span><input name="data_emissao" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_emissao)}/></label>
      <label className="field"><span>Data de agendamento</span><input name="data_agendamento" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_agendamento)}/></label>
      <label className="field"><span>Data de entrega</span><input name="data_entrega" type="date" defaultValue={purchase==='new'?'':dateInput(purchase.data_entrega)}/></label>
    </section>
    <div className="span-2"><PurchaseDocuments projectId={projectId} purchaseId={purchase==='new'?undefined:purchase.id} purchases={purchases} editable drafts={purchase==='new'?documents:undefined} onDraftsChange={purchase==='new'?setDocuments:undefined}/></div>
    <footer className="form-actions span-2"><button type="button" className="app-button" onClick={onClose}>Cancelar</button><button className="app-button primary" disabled={save.isPending}>{save.isPending?'Salvando…':'Salvar Compra'}</button></footer>
  </form></section></div>
}

function MoveItemsDialog({items,purchases,selected,setSelected,target,setTarget,mutation,onClose}:{items:PurchaseItem[];purchases:Purchase[];selected:number[];setSelected:(ids:number[])=>void;target:string;setTarget:(target:string)=>void;mutation:{error:Error|null;isPending:boolean;mutate:()=>void};onClose:()=>void}){
  return <div className="dialog-backdrop"><section className="dialog move-items-dialog"><header><div><small>ORGANIZAÇÃO</small><h2>Mover itens</h2></div><button onClick={onClose}><X/></button></header><div className="move-items-content"><strong>Itens sem Compra</strong><div className="move-item-options">{items.map(item=><label key={item.id}><input type="checkbox" checked={selected.includes(item.id)} onChange={event=>setSelected(event.target.checked?[...selected,item.id]:selected.filter(id=>id!==item.id))}/><span>{item.descricao}</span><small>{item.valor_total===null?'—':formatMoney(item.valor_total)}</small></label>)}</div><label className="field"><span>Mover para Compra</span><select value={target} onChange={event=>setTarget(event.target.value)}><option value="">Selecione a Compra</option>{purchases.map(purchase=><option key={purchase.id} value={purchase.id}>{purchase.descricao}</option>)}</select></label>{mutation.error&&<ErrorNotice message={(mutation.error as Error).message}/>}<footer className="form-actions"><button className="app-button" onClick={onClose}>Cancelar</button><button className="app-button primary" disabled={!selected.length||!target||mutation.isPending} onClick={()=>mutation.mutate()}><CheckSquare2/>Mover {selected.length||''} {selected.length===1?'item':'itens'}</button></footer></div></section></div>
}
